INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('2805b158-2c5b-568c-8749-dc59c3a66d44', 'Breast Imaging Radiologist', 'Mercor', 'Healthcare', 'Remote', 'Contract', 'Specialist / SME', '$300/hr', 'Mercor is hiring fellowship-trained breast imaging radiologists (MDs and DOs) to help build rigorous evaluations of how well AI reads real imaging studies, in partnership with a leading AI lab.

