INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('9abe7dab-a376-5e55-827d-f673bb0ae989', 'Chemist Talent Network', 'Mercor', 'Science', 'Remote', 'Contract', 'Specialist / SME', '$60 - $80/hr', '**About Mercor’s talent network**

