INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('8a331145-67b2-5f57-9bae-b2f547fa418f', 'Critical Care Physician', 'Mercor', 'Healthcare', 'Remote', 'Contract', 'Specialist / SME', '$200/hr', 'Mercor is hiring board-certified critical care physicians (MDs and DOs) to evaluate health AI models in partnership with a leading AI lab.

