INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('6b62f25f-7732-5416-aa6b-2a61f8aef532', 'Education & Training Expert', 'Mercor', 'Finance', 'Remote', 'Contract', 'Specialist / SME', '$30 - $85/hr', 'The research teams behind the best-known AI models come to Mercor for teaching judgment they can''t generate on their own. Your standards and expertise become the rubric that frontier AI is graded against.

