INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('2a05d6cf-b80e-5800-934e-a9a79877921a', 'Financial Analyst Talent Network', 'Mercor', 'Finance', 'Remote', 'Contract', 'Specialist / SME', '$60 - $180/hr', '**About Mercor’s talent network**

