INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('69a8bd6d-b5cf-5512-94cc-23b75cde6cde', 'Materials Science Expert', 'Mercor', 'Science', 'Remote', 'Contract', 'Specialist / SME', '$60 - $120/hr', 'The research teams behind the best-known AI models come to Mercor for materials science judgment they can''t generate on their own. Your standards and expertise become the rubric that frontier AI is graded against.

