INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('2e0f446b-8a7b-5f55-b639-c7170ed38d9c', 'Russian Linguistic Experts', 'Mercor', 'Languages', 'Remote', 'Contract', 'Specialist / SME', '$50/hr', 'Mercor is seeking experienced Russian Linguistic Experts to join a cutting-edge AI research project in partnership with a leading research lab. This role centers on evaluating how effectively a large language model (LLM) performs in Russian-language tasks and on curating high-quality Russian linguistic data to train and improve the model''s understanding and generation capabilities.

