INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('b0a93409-5484-5ffc-881e-b1554969d8ff', 'Software & Firmware Engineering Experts', 'Mercor', 'Coding', 'Remote', 'Contract', 'Specialist / SME', '$100 - $120/hr', '**Mercor is seeking experienced Software and Firmware Engineers** to support an advanced engineering and AI research initiative with a leading technology organization. We are looking for deeply hands-on engineers who have designed, implemented, integrated, tested, debugged, or validated software and firmware that directly interfaces with real-world hardware systems.

