INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('b01a09f6-325d-518c-bfff-2559064e61ab', 'Telugu Linguistic Experts', 'Mercor', 'Languages', 'Remote', 'Contract', 'Specialist / SME', '$30/hr', 'Mercor is seeking experienced Telugu Linguistic Experts to join a cutting-edge AI research project in partnership with a leading research lab. This role centers on evaluating how effectively a large language model (LLM) performs in Telugu-language tasks and on curating high-quality Telugu linguistic data to train and improve the model''s understanding and generation capabilities.

