INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('8f00a6c2-0b8a-5cbd-86e7-6a85a82d91f9', 'Trainium (NKI) Kernel Expert', 'Mercor', 'Data Annotation & RLHF', 'Remote — United States', 'Contract', 'Specialist / SME', '$70 - $90/hr', 'Evaluate the quality, correctness, and hardware-appropriateness of Neuron Kernel Interface (NKI) development tasks used to train and evaluate a frontier AI lab''s models. You''ll assess CUDA→NKI migration fidelity, Trainium-specific performance-optimization quality, and cross-platform numerical-correctness standards — and provide clear, rubric-based written feedback.

