INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('b0604cc5-9d49-4d74-b579-fe7f38fd5fd5', 'Brand and Social Creative Expert', 'micro1', 'Data Annotation & RLHF', 'Remote', 'Contract', '2+ years professional experience', '$50 - $105/hr', 'Role Title: Brand and Social Creative Expert

Role Type: Contractor

