INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('f59ff23d-1cad-470e-8e7c-113f2a3c63e7', 'Business Operations Expert', 'micro1', 'Data Annotation & RLHF', 'Remote', 'Contract', '2+ years professional experience', '$45 - $90/hr', 'Role Title: Business Operations Expert

 Role Type: Contractor

 Location: Remote, global

Opportunity SnapshotPay: Up to $90/hour equivalent

