INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('3adfc3a1-f9a6-4df2-bca4-56bae2a2ebc1', 'Graphic and Editorial Design Expert', 'micro1', 'Data Annotation & RLHF', 'Remote', 'Contract', '2+ years professional experience', '$50 - $105/hr', 'Role Title: Graphic and Editorial Design Expert

