INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('18a809aa-0b7f-4523-ac0e-508c9f0f6f66', 'Open Source Contributor (GitHub)', 'micro1', 'Coding', 'Remote', 'Contract', '2+ years professional experience', '$100 - $150/hr', 'Pay: $100–$150/hour

