INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('31dc936e-0f29-441f-baf9-91c2ff9cc7d4', 'Senior Mobile Developer', 'micro1', 'Coding', 'Remote', 'Contract', '2+ years professional experience', '$50 - $100/hr', 'Role Title: Senior Mobile Software Engineer

