INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('8c0ddeba-5240-4059-9e61-544dd2c8292f', 'Software Engineer (Electron.js)', 'micro1', 'Coding', 'Remote', 'Contract', '2+ years professional experience', 'Competitive', 'Job Title: Software Engineer (Electron.js)

