INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('042646de-db92-5f4f-8b47-31155fab210f', 'Assamese Team Lead', 'sme.careers', 'Languages', 'Remote (3 Countries: Bangladesh, Bhutan, India…)', 'Contract', 'Mid Senior Level', '$30/hr', 'In this hourly, remote contractor role, you will work as an Assamese Quality Assurance Lead (QAL) to oversee quality, consistency, and trainer performance across Assamese AI training projects. You will review AI-generated Assamese content and trainer/QA work, evaluate output quality against project guidelines, provide precise written feedback, and help ensure that all contributors follow the expected standards.

