INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('86919117-757d-54fe-963d-7057da402960', 'OBS Studio Specialist', 'sme.careers', 'Data Annotation & RLHF', 'Remote (3 Countries: Bangladesh, India, Pakistan…)', 'Contract', 'Not Applicable', '$15/hr', 'In this hourly, remote contractor role, you will work as an OBS Studio Specialist (SME) to create realistic, challenging computer-based tasks using OBS Studio and related recording/streaming workflows. You will design practical OBS tasks, document them clearly in SuperAnnotate, ensure your setup supports the task, and record yourself executing the task on your computer.

