INSERT OR IGNORE INTO jobs (id, title, company, category, location, type, experience, compensation, description, skills, responsibilities, status, created_at, updated_at, external_url) VALUES ('0f8a8cc3-8892-5f75-a5d5-954e4116b2e9', 'Odia (Oriya) Team Lead', 'sme.careers', 'Languages', 'Remote (4 Countries: Bangladesh, India, Indonesia…)', 'Contract', 'Mid Senior Level', '$30/hr', 'In this hourly, remote contractor role, you will work as an Odia (Oriya) Quality Assurance Lead (QAL) to oversee quality, consistency, and trainer performance across Odia AI training projects. You will review AI-generated Odia content and trainer/QA work, evaluate output quality against project guidelines, provide precise written feedback, and help ensure that all contributors follow the expected standards.

